<style>.admin-search input{height:38px;width:280px;max-width:50vw;border:1px solid var(--line);border-radius:8px;padding:0 12px;font:14px 'DM Sans',sans-serif}.admin-table .table-head,.admin-table .admin-client-row{grid-template-columns:1.2fr 1.2fr .7fr .7fr auto}.admin-table .table-row small{display:block;font-weight:400;color:var(--muted);font-size:12px}.admin-client+.admin-client{border-top:1px solid #e5ebf3}.client-registration-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 18px;margin:0;padding:0 20px 18px 20px}.client-registration-fields div{min-width:0}.client-registration-fields dt{font-size:9px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:#91a1b0}.client-registration-fields dd{margin:3px 0 0;font-size:11px;color:#536579;overflow-wrap:anywhere}.admin-edit-link{justify-self:start;text-decoration:none;background:#eef4ff;color:#315a9d;border-radius:5px;padding:6px 11px;font-size:11px;font-weight:700}.admin-customer-actions{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.admin-customer-actions form{margin:0}.admin-resend-link,.admin-delete-link{border:0;background:transparent;padding:6px 4px;font:700 11px 'DM Sans',sans-serif;cursor:pointer}.admin-resend-link{color:#1769aa}.admin-delete-link{color:#c0392b}.admin-confirm-backdrop{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:rgba(13,28,49,.58);backdrop-filter:blur(7px)}.admin-confirm-backdrop[hidden]{display:none}.admin-confirm-modal{width:min(440px,100%);padding:32px;border:1px solid rgba(255,255,255,.7);border-radius:24px;background:#fff;box-shadow:0 24px 80px rgba(4,18,38,.3);text-align:center}.admin-confirm-icon{width:54px;height:54px;margin:0 auto 18px;border-radius:18px;background:#fff0ee;color:#d34b3f;font-size:28px;font-weight:800;line-height:54px}.admin-confirm-modal h2{margin:8px 0;color:#17335a;font:800 25px 'Manrope',sans-serif}.admin-confirm-modal p{margin:0;color:#667991;font-size:14px;line-height:1.6}.admin-confirm-note{margin-top:10px!important;font-size:12px!important}.admin-confirm-actions{display:flex;justify-content:center;gap:10px;margin-top:25px}.admin-confirm-actions button{border:0;border-radius:10px;padding:11px 16px;font:700 12px 'DM Sans',sans-serif;cursor:pointer}.admin-confirm-cancel{background:#eef3f8;color:#49627c}.admin-confirm-delete{background:#d34b3f;color:#fff;box-shadow:0 8px 18px rgba(211,75,63,.22)}.admin-pages{margin:14px 0}.admin-pages svg{width:16px}.admin-pages nav>div:first-child{display:none}.topup-actions{display:inline-flex;gap:8px;margin-left:10px}.topup-actions button{border:1px solid #16a34a;background:#16a34a;color:#fff;border-radius:6px;padding:4px 12px;cursor:pointer;font:600 12px 'DM Sans',sans-serif}.topup-actions button.reject{background:#fff;color:#dc2626;border-color:#fca5a5}@media(max-width:760px){.admin-table .table-head{display:none}.admin-table .admin-client-row{grid-template-columns:1fr 1fr;gap:10px;padding:14px}.admin-table .admin-client-row>span:nth-child(3),.admin-table .admin-client-row>b{display:none}.client-registration-fields{grid-template-columns:repeat(2,minmax(0,1fr));padding:0 14px 15px}}@media(max-width:480px){.admin-confirm-modal{padding:25px 20px}.admin-confirm-actions{flex-direction:column-reverse}.admin-confirm-actions button{width:100%}}</style>
<script>document.addEventListener('DOMContentLoaded',function(){var backdrop=document.getElementById('delete-confirm');if(!backdrop)return;var details=document.getElementById('delete-confirm-details');var activeForm=null;function close(){backdrop.hidden=true;activeForm=null}document.querySelectorAll('.admin-delete-link').forEach(function(button){button.addEventListener('click',function(){activeForm=button.closest('form');details.textContent='You are about to permanently delete '+button.dataset.customerName+' ('+button.dataset.customerEmail+').';backdrop.hidden=false;backdrop.querySelector('.admin-confirm-cancel').focus()})});backdrop.querySelector('.admin-confirm-cancel').addEventListener('click',close);backdrop.querySelector('.admin-confirm-delete').addEventListener('click',function(){if(activeForm)HTMLFormElement.prototype.submit.call(activeForm)});backdrop.addEventListener('click',function(event){if(event.target===backdrop)close()});document.addEventListener('keydown',function(event){if(!backdrop.hidden&&event.key==='Escape')close()})});</script>
</body></html>
